package com.nextaicommerce.platform.fba;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import java.util.*;
import java.math.BigDecimal;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import com.nextaicommerce.platform.web.MemberAccessService;
class FbaParentActionsTest {
 final UUID tenant=UUID.randomUUID(),store=UUID.randomUUID();
 FbaShipmentParents.Parent p(String child,Set<String> all){return new FbaShipmentParents.Parent("P","Friendly",null,null,child,null,null,null,all,"source-v1");}
 @Test void declaredMissingChildCannotBecomeAnEligibleImportedSubset(){var projection=new FbaShipmentParents.Projection(Map.of("A",p("child-a",Set.of("child-a","child-b"))),Set.of());assertThatThrownBy(()->FbaParentActions.verified("P",projection)).hasMessageContaining("missing or ambiguous");}
 @Test void duplicateAliasesForOnePhysicalChildAreNotDoubleCounted(){var p=p("same",Set.of("same"));assertThatThrownBy(()->FbaParentActions.verified("P",new FbaShipmentParents.Projection(Map.of("A",p,"alias",p),Set.of()))).hasMessageContaining("not verified");}
 @Test void fullGroupIncludesHiddenAndOffFilterMembersWithExactStableIdentity(){var links=Map.of("B",p("child-b",Set.of("child-a","child-b")),"A",p("child-a",Set.of("child-a","child-b")));var group=FbaParentActions.verified("P",new FbaShipmentParents.Projection(links,Set.of()));assertThat(group.shipments()).containsExactly("A","B");assertThat(group.identity()).hasSize(64);assertThatThrownBy(()->FbaParentActions.verified("OTHER",new FbaShipmentParents.Projection(links,Set.of()))).hasMessageContaining("unavailable");}
 @Test void changedDeclaredMembershipCannotBorrowAnotherGroupsChildren(){assertThatThrownBy(()->FbaParentActions.verified("P",new FbaShipmentParents.Projection(Map.of("A",p("a",Set.of("a","b")),"B",p("b",Set.of("b"))),Set.of()))).hasMessageContaining("not verified");}
 @Test void completedOrUnspecifiedRemainingGroupsFailClosedBeforeBatchPreview(){var batch=mock(FbaBatchDeduction.class);var svc=spy(new FbaParentActions(mock(JdbcTemplate.class),mock(FbaShipmentParents.class),batch,mock(FbaDepletionRepository.class),mock(MemberAccessService.class),mock(FbaReadRepository.class)));doReturn(new FbaParentActions.Group("P","Name",List.of("A","B"),"i","r",1)).when(svc).group(tenant,store,"P");assertThat(svc.preview(tenant,store,"P").blockers()).singleElement().asString().contains("already decreased");doReturn(new FbaParentActions.Group("P","Name",List.of("A","B"),"i","r",2)).when(svc).group(tenant,store,"P");assertThat(svc.preview(tenant,store,"P").plans()).isEmpty();verifyNoInteractions(batch);}
 @Test void largerGroupNeverSilentlyChunks(){var batch=mock(FbaBatchDeduction.class);var svc=spy(new FbaParentActions(mock(JdbcTemplate.class),mock(FbaShipmentParents.class),batch,mock(FbaDepletionRepository.class),mock(MemberAccessService.class),mock(FbaReadRepository.class)));doReturn(new FbaParentActions.Group("P","Name",java.util.stream.IntStream.range(0,26).mapToObj(i->"S"+i).toList(),"i","r",0)).when(svc).group(tenant,store,"P");assertThat(svc.preview(tenant,store,"P").blockers().getFirst()).contains("subset");verifyNoInteractions(batch);}
 @Test void parentMutationIsOneRequiredTransactionAndExistingBatchAlsoRemainsRequired()throws Exception{for(var m:FbaParentActions.class.getDeclaredMethods())if(Set.of("confirm","visibility").contains(m.getName())){var tx=m.getAnnotation(Transactional.class);assertThat(tx).isNotNull();assertThat(tx.propagation()).isEqualTo(org.springframework.transaction.annotation.Propagation.REQUIRED);}for(var m:FbaBatchDeduction.class.getDeclaredMethods())if(m.getName().equals("confirm"))assertThat(m.getAnnotation(Transactional.class).propagation()).isEqualTo(org.springframework.transaction.annotation.Propagation.REQUIRED);}
 @Test void subsetOrRevisionMismatchCannotDelegateAnyStockMutation(){var jdbc=mock(JdbcTemplate.class);var batch=mock(FbaBatchDeduction.class);var access=mock(MemberAccessService.class);when(access.activePlatformAdministrator("owner")).thenReturn(true);var svc=spy(new FbaParentActions(jdbc,mock(FbaShipmentParents.class),batch,mock(FbaDepletionRepository.class),access,mock(FbaReadRepository.class)));doReturn(new FbaParentActions.Group("P","Name",List.of("A","B"),"i","r",0)).when(svc).group(tenant,store,"P");var req=new FbaParentActions.Request("P",UUID.randomUUID(),"i","r","batch",List.of(new FbaBatchDeduction.Choice("A",List.of())));assertThatThrownBy(()->svc.confirm(tenant,store,"owner",req)).hasMessageContaining("Every remaining shipment");verifyNoInteractions(batch);}
 @Test void permissionsAreRecheckedBeforeLockOrQuantityWork(){var jdbc=mock(JdbcTemplate.class);var batch=mock(FbaBatchDeduction.class);var svc=new FbaParentActions(jdbc,mock(FbaShipmentParents.class),batch,mock(FbaDepletionRepository.class),mock(MemberAccessService.class),mock(FbaReadRepository.class));var r=new FbaParentActions.Request("P",UUID.randomUUID(),"i","r","batch",List.of());assertThatThrownBy(()->svc.confirm(tenant,store,"viewer",r)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);verifyNoInteractions(jdbc,batch);}
 @Test void completePendingConfirmationDelegatesAllChildrenAndBindsParentReview(){var jdbc=mock(JdbcTemplate.class);var batch=mock(FbaBatchDeduction.class);var stock=mock(FbaDepletionRepository.class);var access=mock(MemberAccessService.class);when(access.activePlatformAdministrator("owner")).thenReturn(true);var svc=spy(new FbaParentActions(jdbc,mock(FbaShipmentParents.class),batch,stock,access,mock(FbaReadRepository.class)));doReturn(new FbaParentActions.Group("P","Name",List.of("A","B"),"identity","group-r",0)).when(svc).group(tenant,store,"P");var choices=List.of(new FbaBatchDeduction.Choice("A",List.of()),new FbaBatchDeduction.Choice("B",List.of()));UUID request=UUID.randomUUID();var req=new FbaParentActions.Request("P",request,"identity","group-r","batch-r",choices);svc.confirm(tenant,store,"owner",req);verify(stock).lockShipment(tenant,store,"A");verify(stock).lockShipment(tenant,store,"B");verify(batch).confirm(tenant,store,"owner",request,"batch-r",choices,Map.of("parent","P","identity","identity","review","group-r"));verify(jdbc).queryForList(contains("marketplace_connections WHERE tenant_id=? AND id=? FOR UPDATE"),eq(tenant),eq(store));}
 @Test void changedSourceOrCompletedStateBlocksWholeParentBeforeBatch(){for(int decreased:List.of(0,1,2)){var jdbc=mock(JdbcTemplate.class);var batch=mock(FbaBatchDeduction.class);var access=mock(MemberAccessService.class);when(access.activePlatformAdministrator("owner")).thenReturn(true);var svc=spy(new FbaParentActions(jdbc,mock(FbaShipmentParents.class),batch,mock(FbaDepletionRepository.class),access,mock(FbaReadRepository.class)));doReturn(new FbaParentActions.Group("P","Name",List.of("A","B"),"identity","current-r",decreased)).when(svc).group(tenant,store,"P");var req=new FbaParentActions.Request("P",UUID.randomUUID(),"identity",decreased==0?"stale-r":"current-r","batch-r",List.of(new FbaBatchDeduction.Choice("A",List.of()),new FbaBatchDeduction.Choice("B",List.of())));assertThatThrownBy(()->svc.confirm(tenant,store,"owner",req)).hasMessageContaining(decreased==0?"changed":"already decreased");verifyNoInteractions(batch);}}
 @Test void mixedParentPreviewsEveryRemainingChildAndNeverAlreadyDecreased(){
  var jdbc=mock(JdbcTemplate.class);var parents=mock(FbaShipmentParents.class);var batch=mock(FbaBatchDeduction.class);
  when(jdbc.queryForList(startsWith("SELECT shipment_id FROM amazon_fba_shipments"),eq(String.class),eq(tenant),eq(store))).thenReturn(List.of("A","B"));
  when(parents.read(eq(tenant),eq(store),any())).thenReturn(new FbaShipmentParents.Projection(Map.of("A",p("a",Set.of("a","b")),"B",p("b",Set.of("a","b"))),Set.of()));
  when(jdbc.queryForList(startsWith("SELECT s.shipment_id,md5"),any(Object[].class))).thenReturn(List.of(Map.of("shipment_id","A","decreased_id","done","source_revision","a"),Map.of("shipment_id","B","source_revision","b")));
  when(batch.preview(tenant,store,List.of("B"))).thenReturn(new FbaBatchDeduction.Review(List.of(new FbaBatchDeduction.Plan(new FbaDepletionRepository.Preview("B",null,"Warehouse","ZIP","r",List.of(),List.of(),List.of(),List.of(),false,false,true),List.of())),List.of(),"batch"));
  var svc=new FbaParentActions(jdbc,parents,batch,mock(FbaDepletionRepository.class),mock(MemberAccessService.class),mock(FbaReadRepository.class));var result=svc.preview(tenant,store,"P");
  assertThat(result.plans()).extracting(v->v.shipment().shipment()).containsExactly("B");assertThat(result.blockers()).isEmpty();verify(batch).preview(tenant,store,List.of("B"));
 }
 @Test void mixedParentConfirmsOnlyAllRemainingAndLocksCompletedSiblingsToo(){
  var jdbc=mock(JdbcTemplate.class);var batch=mock(FbaBatchDeduction.class);var stock=mock(FbaDepletionRepository.class);var access=mock(MemberAccessService.class);when(access.activePlatformAdministrator("owner")).thenReturn(true);
  var svc=spy(new FbaParentActions(jdbc,mock(FbaShipmentParents.class),batch,stock,access,mock(FbaReadRepository.class)));doReturn(new FbaParentActions.Group("P","Name",List.of("A","B","C"),"i","r",1,List.of("B","C"))).when(svc).group(tenant,store,"P");
  UUID request=UUID.randomUUID();var choices=List.of(new FbaBatchDeduction.Choice("B",List.of()),new FbaBatchDeduction.Choice("C",List.of()));svc.confirm(tenant,store,"owner",new FbaParentActions.Request("P",request,"i","r","batch",choices));
  verify(stock).lockShipment(tenant,store,"A");verify(stock).lockShipment(tenant,store,"B");verify(stock).lockShipment(tenant,store,"C");verify(batch).confirm(tenant,store,"owner",request,"batch",choices,Map.of("parent","P","identity","i","review","r"));
 }
 @Test void remainingSubsetOrAlreadyDoneChildIsRejectedWithoutMutation(){for(var selected:List.of(List.of("B"),List.of("A","B","C"),List.of("B","B","C"))){var jdbc=mock(JdbcTemplate.class);var batch=mock(FbaBatchDeduction.class);var access=mock(MemberAccessService.class);when(access.activePlatformAdministrator("owner")).thenReturn(true);var svc=spy(new FbaParentActions(jdbc,mock(FbaShipmentParents.class),batch,mock(FbaDepletionRepository.class),access,mock(FbaReadRepository.class)));doReturn(new FbaParentActions.Group("P","Name",List.of("A","B","C"),"i","r",1,List.of("B","C"))).when(svc).group(tenant,store,"P");var choices=selected.stream().map(id->new FbaBatchDeduction.Choice(id,List.of())).toList();assertThatThrownBy(()->svc.confirm(tenant,store,"owner",new FbaParentActions.Request("P",UUID.randomUUID(),"i","r","b",choices))).hasMessageContaining("Every remaining");verifyNoInteractions(batch);}}
 @Test void signedReplayCanReachStoredReceiptAfterRemainingBecomesEmpty(){var jdbc=mock(JdbcTemplate.class);when(jdbc.queryForObject(startsWith("SELECT EXISTS(SELECT 1 FROM fba_shipment_depletions"),eq(Boolean.class),any(Object[].class))).thenReturn(true);var batch=mock(FbaBatchDeduction.class);var access=mock(MemberAccessService.class);when(access.activePlatformAdministrator("owner")).thenReturn(true);var svc=spy(new FbaParentActions(jdbc,mock(FbaShipmentParents.class),batch,mock(FbaDepletionRepository.class),access,mock(FbaReadRepository.class)));doReturn(new FbaParentActions.Group("P","Name",List.of("A","B"),"i","new-r",2,List.of())).when(svc).group(tenant,store,"P");UUID request=UUID.randomUUID();var choices=List.of(new FbaBatchDeduction.Choice("B",List.of()));svc.confirm(tenant,store,"owner",new FbaParentActions.Request("P",request,"i","old-r","batch",choices));verify(batch).confirm(tenant,store,"owner",request,"batch",choices,Map.of("parent","P","identity","i","review","old-r"));}
 @Test void concurrentChildDecreaseInvalidatesPreviewBeforeAnyBatchMutation(){var jdbc=mock(JdbcTemplate.class);var batch=mock(FbaBatchDeduction.class);var access=mock(MemberAccessService.class);when(access.activePlatformAdministrator("owner")).thenReturn(true);var svc=spy(new FbaParentActions(jdbc,mock(FbaShipmentParents.class),batch,mock(FbaDepletionRepository.class),access,mock(FbaReadRepository.class)));doReturn(new FbaParentActions.Group("P","Name",List.of("A","B"),"i","old",0),new FbaParentActions.Group("P","Name",List.of("A","B"),"i","new",1,List.of("B"))).when(svc).group(tenant,store,"P");assertThatThrownBy(()->svc.confirm(tenant,store,"owner",new FbaParentActions.Request("P",UUID.randomUUID(),"i","old","batch",List.of(new FbaBatchDeduction.Choice("A",List.of()),new FbaBatchDeduction.Choice("B",List.of()))))).hasMessageContaining("changed");verifyNoInteractions(batch);}
}
